// Pre-sorted phrases by character length descending to prevent greedy substring collisions
export const SORTED_PHRASES = Object.keys(PHRASE_DICTIONARY)
  .sort((a, b) => b.length - a.length)
  .map((phrase) => ({
    phrase,
    translations: PHRASE_DICTIONARY[phrase],
  }));

function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Universal key-based translation helper.
 */
export function translate(key, lang = 'en', defaultText = '') {
  const effectiveLang = TRANSLATIONS[lang] ? lang : 'en';
  if (TRANSLATIONS[effectiveLang] && TRANSLATIONS[effectiveLang][key]) {
    return TRANSLATIONS[effectiveLang][key];
  }
  if (TRANSLATIONS.en && TRANSLATIONS.en[key]) {
    return TRANSLATIONS.en[key];
  }
  return defaultText || key;
}

/**
 * Translate arbitrary English text to target language via key or phrase dictionary.
 */
export function translateText(text, lang = 'en') {
  if (!text || typeof text !== 'string' || !lang || lang === 'en') return text;
  const trimmed = text.trim();
  if (PHRASE_DICTIONARY[trimmed] && PHRASE_DICTIONARY[trimmed][lang]) {
    return PHRASE_DICTIONARY[trimmed][lang];
  }
  return text;
}

/**
 * Deep multi-pass text translator for arbitrary UI content.
 */
export function translateDeepText(text, lang = 'en') {
  if (!text || typeof text !== 'string' || !lang || lang === 'en') return text;
  const trimmed = text.trim();
  if (!trimmed) return text;

  // 1. Exact match in PHRASE_DICTIONARY
  if (PHRASE_DICTIONARY[trimmed] && PHRASE_DICTIONARY[trimmed][lang]) {
    const leadSpace = text.match(/^\s*/)[0];
    const trailSpace = text.match(/\s*$/)[0];
    return leadSpace + PHRASE_DICTIONARY[trimmed][lang] + trailSpace;
  }

  // 2. Exact match in TRANSLATIONS keys
  if (TRANSLATIONS.en) {
    for (const [k, v] of Object.entries(TRANSLATIONS.en)) {
      if (typeof v === 'string' && v.toLowerCase() === trimmed.toLowerCase()) {
        if (TRANSLATIONS[lang] && TRANSLATIONS[lang][k]) {
          const leadSpace = text.match(/^\s*/)[0];
          const trailSpace = text.match(/\s*$/)[0];
          return leadSpace + TRANSLATIONS[lang][k] + trailSpace;
        }
      }
    }
  }

  // 3. Multi-phrase substring replacements (longest matches first)
  let result = text;
  for (const entry of SORTED_PHRASES) {
    const origPhrase = entry.phrase;
    const trans = entry.translations[lang];
    if (!trans || origPhrase.length < 3) continue;

    if (result.includes(origPhrase)) {
      result = result.split(origPhrase).join(trans);
    } else {
      const idx = result.toLowerCase().indexOf(origPhrase.toLowerCase());
      if (idx !== -1) {
        try {
          const reg = new RegExp(escapeRegExp(origPhrase), 'gi');
          result = result.replace(reg, trans);
        } catch {
          // ignore regex errors
        }
      }
    }
  }

  return result;
}

/**
 * Universal Recursive DOM Text Walker with Loss-less Original English Memory
 */
export function walkAndTranslateDOM(rootNode, targetLang) {
  if (!rootNode || typeof document === 'undefined') return;
  const isEn = !targetLang || targetLang === 'en';

  // 1. Text Nodes Walker
  const walker = document.createTreeWalker(
    rootNode,
    NodeFilter.SHOW_TEXT,
    {
      acceptNode: (node) => {
        if (!node.nodeValue || !node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
        const parent = node.parentElement;
        if (!parent) return NodeFilter.FILTER_REJECT;
        const tag = parent.tagName ? parent.tagName.toUpperCase() : '';
        if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'NOSCRIPT' || tag === 'PRE' || tag === 'CODE') {
          return NodeFilter.FILTER_REJECT;
        }
        // Skip language picker itself so language labels remain legible in their native script
        if (parent.closest('.header-lang-picker') || parent.id === 'orca-header-lang-select' || parent.id === 'globalAppLanguageSelect') {
          return NodeFilter.FILTER_REJECT;
        }
        return NodeFilter.FILTER_ACCEPT;
      }
    }
  );

  const textNodes = [];
  let cur = walker.nextNode();
  while (cur) {
    textNodes.push(cur);
    cur = walker.nextNode();
  }

  for (const node of textNodes) {
    if (node.__orca_orig === undefined) {
      node.__orca_orig = node.nodeValue;
    }
    const orig = node.__orca_orig;
    if (!orig || !orig.trim()) continue;

    if (isEn) {
      if (node.nodeValue !== orig) node.nodeValue = orig;
    } else {
      const trans = translateDeepText(orig, targetLang);
      if (trans && trans !== node.nodeValue) {
        node.nodeValue = trans;
      }
    }
  }

  // 2. Attributes Walker (placeholders, titles, aria-labels)
  const elementsWithAttrs = rootNode.querySelectorAll ? rootNode.querySelectorAll('[placeholder], [title], [aria-label]') : [];
  elementsWithAttrs.forEach((el) => {
    if (el.closest('.header-lang-picker') || el.id === 'orca-header-lang-select' || el.id === 'globalAppLanguageSelect') return;

    ['placeholder', 'title', 'aria-label'].forEach((attr) => {
      const origKey = `__orca_orig_${attr}`;
      if (el[origKey] === undefined && el.hasAttribute(attr)) {
        el[origKey] = el.getAttribute(attr);
      }
      const origVal = el[origKey];
      if (origVal && origVal.trim()) {
        if (isEn) {
          if (el.getAttribute(attr) !== origVal) el.setAttribute(attr, origVal);
        } else {
          const transVal = translateDeepText(origVal, targetLang);
          if (transVal && el.getAttribute(attr) !== transVal) {
            el.setAttribute(attr, transVal);
          }
        }
      }
    });
  });
}
